## Code Example
```javascript
// Pseudo-sign-verify example (Node.js)
const crypto = require('crypto');
async function verify(manifestPath, sigPath, pubKeyPath){
  const m = await require('fs').promises.readFile(manifestPath);
  const s = await require('fs').promises.readFile(sigPath);
  const pub = await require('fs').promises.readFile(pubKeyPath);
  const v = crypto.createVerify('RSA-SHA256');
  v.update(m); v.end();
  return v.verify(pub, s);
}
```

